def split_array_brute(nums, k):
    n = len(nums)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]

    def helper(start, pieces_left):
        if pieces_left == 1:
            return prefix[n] - prefix[start]              # remaining sum is the last piece
        best = float('inf')
        for end in range(start + 1, n - pieces_left + 2):    # try every split point
            piece_sum = prefix[end] - prefix[start]
            best = min(best, max(piece_sum, helper(end, pieces_left - 1)))
        return best

    return helper(0, k)

