def split_array(nums, k):
    def pieces_needed(cap):
        count, current = 1, 0
        for num in nums:
            if current + num > cap:                 # would exceed the cap, start a new piece
                count += 1
                current = 0
            current += num
        return count

    lo, hi = max(nums), sum(nums)
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if pieces_needed(mid) <= k:
            hi = mid                                  # feasible, search for a smaller cap
        else:
            lo = mid + 1                               # infeasible, need a larger cap
    return lo

