        int lo = 0, hi = 0;
        for (int num : nums) { lo = Math.max(lo, num); hi += num; }
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (piecesNeeded(nums, mid) <= k) hi = mid;             // feasible, search smaller
            else lo = mid + 1;                                         // infeasible, need larger
        }
        return lo;
    }
